using System.Reflection;
using System.Text;
using TomasAI.IFM.Application.MarketData.Contracts;

// Development-only generator. Output is ordinary checked-in strongly typed C#;
// production routing uses no reflection, generic dispatcher or service locator.
if (args.Length != 1) throw new ArgumentException("Expected the managed/Api output directory.");
var nullability = new NullabilityInfoContext();
string Name(Type type, NullabilityInfo? info = null)
{
    if (type.IsByRef) return Name(type.GetElementType()!, info);
    if (Nullable.GetUnderlyingType(type) is { } underlying) return Name(underlying, info?.GenericTypeArguments.FirstOrDefault()) + "?";
    string text;
    if (type.IsArray) text = Name(type.GetElementType()!, info?.ElementType) + "[]";
    else if (type.IsGenericType)
    {
        var root = type.GetGenericTypeDefinition().FullName!.Split('`')[0].Replace('+', '.');
        text = "global::" + root + "<" + string.Join(", ", type.GetGenericArguments().Select((t, i) => Name(t, info?.GenericTypeArguments.ElementAtOrDefault(i)))) + ">";
    }
    else text = type == typeof(void) ? "void" : "global::" + type.FullName!.Replace('+', '.');
    if (!type.IsValueType && info?.ReadState == NullabilityState.Nullable) text += "?";
    return text;
}
string Parameter(ParameterInfo p)
{
    var value = (p.IsOut ? "out " : p.ParameterType.IsByRef ? "ref " : "") + Name(p.ParameterType, nullability.Create(p)) + " " + p.Name;
    if (!p.HasDefaultValue) return value;
    return value + " = " + (p.DefaultValue is bool flag ? (flag ? "true" : "false") : p.DefaultValue is null && !p.ParameterType.IsValueType ? "null" : "default");
}
bool Host(MethodInfo method) => method.GetCustomAttribute<MarketDataHostOperationAttribute>() is not null
    || method.GetParameters().Any(p => p.ParameterType == typeof(SubscriptionAcquireRequest))
    || method.Name is "RenewSubscriptionLeaseAsync" or "ReleaseSubscriptionLeaseAsync" or "AcquireSelectedSubscriptionLeasesAsync" or "GetSubscriptionLeasesAsync";
var methods = typeof(IMarketDataApi).GetMethods().Where(m => !m.IsSpecialName).OrderBy(m => m.Name, StringComparer.Ordinal).ThenBy(m => m.ToString(), StringComparer.Ordinal).ToArray();
var facade = new StringBuilder("// Generated by qualification/ApiFacadeGenerator. Do not hand-edit method routing.\nnamespace TomasAI.IFM.Application.MarketData.Rust.Api;\n\npublic sealed partial class RustMarketDataApi\n{\n");
var host = new StringBuilder("// Generated by qualification/ApiFacadeGenerator. Required operations have no default bodies.\nnamespace TomasAI.IFM.Application.MarketData.Rust.Api;\n\n/// <summary>Required native Host application capabilities. Implementations own persistence,\n/// references, subscriptions and publication around native data-plane services.</summary>\npublic interface IRustMarketDataHostServices\n{\n    /// <summary>The prepared native-backed strategy snapshot cache.</summary>\n    global::TomasAI.IFM.Application.MarketData.Contracts.IOptionChainCache OptionChainCache { get; }\n");
var application = new StringBuilder("// Generated by qualification/ApiFacadeGenerator. Required operations have no default bodies.\nnamespace TomasAI.IFM.Application.MarketData.Rust.Api;\n\n/// <summary>Required command/query adapter capabilities. Rust owns every live resource;\n/// implementations must not construct managed epochs, leases or renewal loops.</summary>\npublic interface IRustMarketDataApplicationServices : global::System.IAsyncDisposable\n{\n");
var prototype = new StringBuilder("// Generated by qualification/ApiFacadeGenerator. Preserved prototype compatibility only.\nnamespace TomasAI.IFM.Application.MarketData.Rust.Api;\n\ninternal sealed class PrototypeApplicationServices(global::TomasAI.IFM.Application.MarketData.Databento.DatabentoMarketDataApi source) : IRustMarketDataApplicationServices\n{\n    public global::System.Threading.Tasks.ValueTask DisposeAsync() => source.DisposeAsync();\n");
foreach (var method in methods)
{
    var result = Name(method.ReturnType, nullability.Create(method.ReturnParameter));
    var parameters = string.Join(", ", method.GetParameters().Select(Parameter));
    var arguments = string.Join(", ", method.GetParameters().Select(p => (p.IsOut ? "out " : p.ParameterType.IsByRef ? "ref " : "") + p.Name));
    var signature = result + " " + method.Name + "(" + parameters + ")";
    if(method.Name is not (nameof(IMarketDataApi.StartAsync) or nameof(IMarketDataApi.StopAsync))) facade.Append("    /// <inheritdoc/>\n    public ").Append(signature).Append(" => ").Append(Host(method) ? "host" : "application").Append('.').Append(method.Name).Append('(').Append(arguments).Append(");\n");
    if (!Host(method))
    {
        application.Append("    /// <summary>Forwards the ").Append(method.Name).Append(" command/query.</summary>\n    ").Append(signature).Append(";\n");
        prototype.Append("    public ").Append(signature).Append(" => source.").Append(method.Name).Append('(').Append(arguments).Append(");\n");
    }
    if (Host(method)) host.Append("    /// <summary>Executes the ").Append(method.Name).Append(" application operation.</summary>\n    ").Append(signature).Append(";\n");
}
facade.Append("}\n"); host.Append("}\n"); application.Append("}\n"); prototype.Append("}\n");
Directory.CreateDirectory(args[0]);
File.WriteAllText(Path.Combine(args[0], "RustMarketDataApi.Operations.cs"), facade.ToString(), new UTF8Encoding(false));
File.WriteAllText(Path.Combine(args[0], "IRustMarketDataHostServices.cs"), host.ToString(), new UTF8Encoding(false));
File.WriteAllText(Path.Combine(args[0], "IRustMarketDataApplicationServices.cs"), application.ToString(), new UTF8Encoding(false));
File.WriteAllText(Path.Combine(args[0], "PrototypeApplicationServices.cs"), prototype.ToString(), new UTF8Encoding(false));
Console.WriteLine($"Generated {methods.Length} explicit facade routes; {methods.Count(Host)} required Host capabilities, no default interface fallthrough.");
